 {!status?<div className="empty">正在连接本机档案服务…</div>:!prepared&&panel!=='settings'?<main className="onboarding"><div className="onboarding-title"><span className="brand-symbol">档</span><h1>准备你的本机聊天档案</h1><p>选择数据目录，确认自己的身份，再选择需要维护的会话。</p></div><ol><li><strong>目录与账号</strong><span>{status.account?'已选择 '+status.account.label:'选择微信 db_storage 或解密库根目录'}</span></li><li><strong>通讯录与身份</strong><span>加密库先提取密钥与准备通讯录；明文库直接确认内部身份。</span></li><li><strong>维护范围</strong><span>勾选会话后直接导入，或保存关注范围再更新。</span></li></ol><button className="primary" onClick={()=>open('settings')}>{status.account?'继续准备身份':'开始设置目录'}</button></main>:<main className="workspace"><aside className="sessions"><div className="section-head"><h1>会话</h1><button onClick={()=>open('selection')}>批量操作</button></div><div className="session-tools"><label className="project-picker"><span className="muted">项目</span><select aria-label="会话项目" value={groupId} onChange={e=>setGroupId(e.target.value)}><option value="">全部会话</option>{groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select><button onClick={()=>manageProjects(selected)}>管理</button></label>{groupId&&<div className="row project-actions"><button disabled={busy} onClick={()=>run(()=>previewGroup('update'))}>更新本组</button><button onClick={()=>run(()=>previewGroup('analysis'))}>分析本组</button><button onClick={()=>run(()=>previewGroup('export'))}>导出本组</button></div>}<input aria-label="搜索会话与联系人" type="search" value={q} onChange={e=>setQ(e.target.value)} placeholder="搜索会话、联系人、微信号"/><div className="row"><details className="type-picker"><summary>会话类型（{category.length}/{Object.keys(categories).length}）</summary><div className="type-options">{Object.entries(categories).map(([k,v])=><label className="check" key={k}><input type="checkbox" checked={category.includes(k)} disabled={category.length===1&&category.includes(k)} onChange={()=>setCategory(s=>s.includes(k)?s.filter(x=>x!==k):[...s,k])}/>{v}</label>)}<button onClick={()=>setCategory(Object.keys(categories))}>全选类型</button></div></details><button aria-expanded={filters} onClick={()=>setFilters(!filters)}>列表筛选{ls||le?' •':''}</button></div>{filters&&<div className="filter-box"><label>列表开始日期<input type="date" value={ls} onChange={e=>setLs(e.target.value)}/></label><label>列表结束日期<input type="date" value={le} onChange={e=>setLe(e.target.value)}/></label><label>列表日期含义<select value={dateMode} onChange={e=>setDateMode(e.target.value)}><option value="activity">时段内有已归档消息</option><option value="span">完整起止位于时段内</option></select></label><label className="check"><input type="checkbox" checked={unknown} onChange={e=>setUnknown(e.target.checked)}/>包含日期未知（待导入）</label><label>排序<select value={sort} onChange={e=>setSort(e.target.value)}><option value="recent">最近消息</option><option value="count">消息数量</option></select></label><p>列表日期只筛选会话，与阅读、导出日期独立。</p><button onClick={()=>{setQ('');setCategory(Object.keys(categories));setLs('');setLe('');setUnknown(true)}}>清除列表筛选</button></div>}<div className="list-summary"><span>{q.trim()||category.length<Object.keys(categories).length||groupId||ls||le?`找到 ${chats.length} 个，共 ${all.length} 个`:`共 ${all.length} 个会话`}</span><button className="link" onClick={()=>setSelected(s=>Array.from(new Set([...s,...chats.map(c=>c.username)])))}>全选当前列表</button></div></div><SessionList rows={chats} header={<>{listLoading&&<div className="loading">正在筛选…</div>}{listError&&<div className="alert">{listError}</div>}{!listLoading&&!chats.length&&<div className="empty">{all.length?'当前筛选无结果，请调整条件。':'暂无会话，请从数据设置准备通讯录或发现历史会话。'}</div>}</>}>{(c,i,focus)=><div key={c.username} className={'chat-row '+(active===c.username?'active':'')} role="listitem" aria-setsize={chats.length} aria-posinset={i+1} onContextMenu={e=>showChatMenu(e,c)} onKeyDown={e=>{if(e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10'))showChatMenu(e,c)}}><input aria-label={'选择 '+c.name+' '+c.username} type="checkbox" checked={selected.includes(c.username)} onChange={()=>toggle(c.username)}/><button className="chat-select" aria-haspopup="menu" onClick={()=>choose(c)} onKeyDown={e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const next=chats[Math.max(0,Math.min(chats.length-1,i+(e.key==='ArrowDown'?1:-1)))];choose(next);focus(chats.indexOf(next))}}}><span className="chat-title"><strong title={c.name}>{c.name}</strong><small>{c.imported?c.total.toLocaleString():'待导入'}</small></span><span className="chat-sub">{c.followed&&<span className="follow-dot"/>}{categories[c.category]||c.category}　{c.imported?c.preview||'已归档':c.username}</span>{c.match_reasons?.length?<small className="reason" title={c.match_reasons.join('；')}>{c.match_reasons.join('；')}</small>:null}</button></div>}</SessionList><div className="session-footer"><button className="link" onClick={()=>open('hidden')}>隐藏会话管理</button><button className="link" onClick={()=>setSelected((status.config.followed_usernames||[]).filter((u:string)=>allUsers.has(u)))}>勾选已关注</button></div></aside>
 <section className="reader"><div className="reading-header"><div><h2 title={view.startsWith('analysis')&&analysisScope?`所选 ${analysisScope.length} 个会话`:chat?.name}>{view.startsWith('analysis')?'聊天内容分析':chat?.name||'选择会话开始阅读'}</h2><span className="muted">{view.startsWith('analysis')?null:chat?`${categories[chat.category]||chat.category}　${chat.username}`:'左侧搜索联系人，也可找到其发言的已归档群聊'}</span></div><div className="row"><button disabled={!chat} onClick={()=>open('details')}>会话详情</button><button className="primary" disabled={!chat} onClick={()=>{setExportMode('all');open('export',[active])}}>{view.startsWith('analysis')?'导出当前会话':'导出'}</button></div></div><div className={'explore-toolbar '+(view.startsWith('analysis')?'analysis-toolbar':'')}><div className="tabs">{[['read','阅读'],['analysis','分析']].map(([k,v])=><button key={k} aria-pressed={view===k||(k==='analysis'&&view==='analysis-read')} onClick={()=>{switchView(k)}}>{v}</button>)}</div><div className="message-range"><label>消息日期<input aria-label="消息开始日期" type="date" value={ms} onChange={e=>{setMs(e.target.value);setOffset(0);setDay('')}}/></label><span>至</span><input aria-label="消息结束日期" type="date" value={me} onChange={e=>{setMe(e.target.value);setOffset(0);setDay('')}}/><button className="link" onClick={()=>{setMs('');setMe('');setDay('');setOffset(0)}}>全部日期</button></div><button aria-expanded={searchOpen} onClick={()=>setSearchOpen(v=>!v)}>{searchOpen?'收起搜索工具':'搜索消息'}</button>{searchOpen&&<form className="message-search" onSubmit={e=>{e.preventDefault();setSearch(mq.trim());setOffset(0);setDay('')}}><input aria-label="搜索消息正文" placeholder="搜索当前会话正文，例如：报销" value={mq} onChange={e=>setMq(e.target.value)}/><button className="primary">搜索</button><label className="check"><input type="checkbox" checked={transcripts} onChange={e=>{setTranscripts(e.target.checked);setOffset(0)}}/>包含成功转写</label></form>}<div className="query-summary" hidden={view.startsWith('analysis')&&!search&&!day}><span>{view.startsWith('analysis')?null:<>{search?`关键词「${search}」 · ${transcripts?'正文及成功转写':'仅正文'} · `:''}{day?`${day} · `:''}{(messagePending?'…':result.total.toLocaleString())} 条{search?'命中':'已归档消息'}{messagePending?' · 更新中…':''}</>}</span><div>{search&&<button className="link" onClick={()=>{setSearch('');setMq('');setContext(null);setOffset(0)}}>清除关键词</button>}{day&&<button className="link" onClick={()=>{setDay('');setOffset(0)}}>清除日筛选</button>}{search&&<button className="link" onClick={()=>{setExportMode('search');open('export',[active])}}>导出命中</button>}</div></div></div>
 {context&&<div className="context-banner">前后文（不计入命中导出）<button onClick={()=>{setContext(null);setView(contextView.current);requestAnimationFrame(()=>{if(reader.current)reader.current.scrollTop=contextPosition.current})}}>返回命中结果</button></div>}
 <div className="reading-scroll" ref={reader} onScroll={saveView}><div hidden={!view.startsWith('analysis')}><AnalysisWorkspace key={status.account?.id||''} accountId={status.account?.id||''} active={active} chats={all} selected={selected} scope={analysisScope} onScope={setAnalysisScope} onAnalyzeSelected={analyzeSelected} q={search} start={ms} end={me} transcripts={transcripts} revision={revision} enabled={view.startsWith('analysis')} reading={view==='analysis-read'} onReading={reading=>{if(reading&&currentView.current==='analysis')viewPositions.current.analysis=reader.current?.scrollTop||0;setView(v=>v.startsWith('analysis')?(reading?'analysis-read':'analysis'):v)}}/></div>{!view.startsWith('analysis')&&(messageError?<div className="empty" role="alert">加载失败：{messageError}<button onClick={()=>setRevision(v=>v+1)}>重试</button></div>:messagePending?<div className="message-skeleton" role="status">正在读取当前会话与条件的消息…<div/><div/><div/></div>:!active?<div className="empty">选择左侧会话开始阅读</div>:!(context||result.messages).length?<div className="empty">{chat?.imported?'当前消息条件无结果，请调整日期或关键词。':'此会话待导入。勾选后点击“导入所选”，处理此会话全部历史。'}</div>:<div className="messages">{[...(context||result.messages)].reverse().map(renderMessage)}</div>)}</div>{!view.startsWith('analysis')&&<footer className="reading-footer"><span>{context?'上下文独立于消息筛选':result.total?`第 ${Math.floor(offset/50)+1} / ${Math.ceil(result.total/50)} 页，每页最多 50 条，按时间从新到旧`:'消息日期与列表日期独立'}</span><div className="row"><button disabled={messagePending||offset+50>=result.total||!!context} onClick={()=>setOffset(v=>v+50)}>更早 50 条</button><button disabled={messagePending||offset===0||!!context} onClick={()=>setOffset(v=>Math.max(0,v-50))}>更新 50 条</button></div></footer>}</section>
 {selected.length>0&&<div className="bulk"><strong>已选 {selected.length}</strong><span>列表筛选外 {hidden}</span><button onClick={()=>open('selection')}>查看全部选择</button><button disabled={busy} onClick={()=>run(()=>task('update',selected))}>导入所选</button><button disabled={busy} onClick={()=>run(()=>task('transcribe',selected))}>转写语音</button><button onClick={analyzeSelected}>分析所选（{selected.length}）</button><button onClick={()=>{setExportMode('all');open('export')}}>导出所选</button><button className="link" onClick={()=>setSelected([])}>取消选择</button><small>导入 / 转写处理所选会话全部历史</small></div>}</main>}
